public class InnerChannelS3DestinationConfigurationFactory(Action<Humidifier.Kinesis.ChannelTypes.S3DestinationConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Kinesis.ChannelTypes.S3DestinationConfiguration>
{

    internal InnerChannelDeadLetterQueueS3ConfigurationFactory DeadLetterQueueS3ConfigurationFactory { get; set; }

    internal InnerChannelS3StorageConfigurationFactory StorageConfigurationFactory { get; set; }

    protected override Humidifier.Kinesis.ChannelTypes.S3DestinationConfiguration Create()
    {
        var s3DestinationConfigurationResult = CreateS3DestinationConfiguration();
        factoryAction?.Invoke(s3DestinationConfigurationResult);

        return s3DestinationConfigurationResult;
    }

    private Humidifier.Kinesis.ChannelTypes.S3DestinationConfiguration CreateS3DestinationConfiguration()
    {
        var s3DestinationConfigurationResult = new Humidifier.Kinesis.ChannelTypes.S3DestinationConfiguration();

        return s3DestinationConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Kinesis.ChannelTypes.S3DestinationConfiguration result)
    {
        base.CreateChildren(result);

        result.DeadLetterQueueS3Configuration ??= DeadLetterQueueS3ConfigurationFactory?.Build();
        result.StorageConfiguration ??= StorageConfigurationFactory?.Build();
    }

} // End Of Class

